// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
async function report(helpers, cfg, body) {
  // Tells the dashboard how the hunt is going. Never stops the hunt if the dashboard can't be reached.
  if (!cfg || !cfg.run_id || !cfg.dashboard_url) return;
  try {
    await helpers.httpRequest({ url: cfg.dashboard_url + '/api/hunt/progress', method: 'POST', headers: { 'X-Ingestion-Key': KEY() }, body: { runId: cfg.run_id, ...body }, json: true, timeout: 5000 });
  } catch (e) {}
}

  // Google Trends, last 24 hours. Never stops the hunt: any failure is noted and the hunt goes on.
  //  - Trending searches per country (public RSS feed) with their news photos -> dashboard checks photos for leather jackets
  //  - Rising / top searches around "leather jacket" (Trends explore data, rate limited by Google: skipped on 429)
  const body = $('Leather Hunt Webhook').first().json.body || {};
  const list = v => (Array.isArray(v) ? v : String(v || '').split(/[\n,]/)).map(s => String(s).trim()).filter(Boolean);
  const markets = list(body.markets).map(m => m.toUpperCase()).filter(m => ['US', 'UK', 'CA'].includes(m));
  const geos = (markets.length ? markets : ['US', 'UK', 'CA']).map(m => m === 'UK' ? 'GB' : m);
  const dashboard = String(body.dashboardUrl || 'http://host.docker.internal:4300').replace(/\/+$/, '');
  const started = Date.now();
  const timeLeft = () => Date.now() - started < 40000;
  const JACKET = /\b(leather|jacket|jackets|biker|bomber|moto|motorcycle|suede|shearling|aviator|racer|trucker|blouson)\b/i;
  const NOT_WANTED = /\b(cheap|diy|how to|clean|repair|meme|lyrics|costume)\b/i;

  const decode = s => String(s || '').replace(/<!\[CDATA\[|\]\]>/g, '').replace(/&amp;/g, '&').replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim();
  const tag = (xml, name) => decode((xml.match(new RegExp(`<${name}>([\\s\\S]*?)</${name}>`, 'i')) || [])[1]);
  const fetchText = async (url, headers = {}) => {
    const res = await this.helpers.httpRequest({ url, method: 'GET', headers, timeout: 15000, returnFullResponse: true, ignoreHttpStatusErrors: true, encoding: 'text' });
    return { status: res.statusCode, text: typeof res.body === 'string' ? res.body : JSON.stringify(res.body), headers: res.headers || {} };
  };

  const out = { fetched_at: new Date().toISOString(), run_id: String(body.runId || ''), mode: body.mode === 'trend' ? 'trend' : 'normal', markets: {}, notes: [] };

  // 1) Trending searches, last 24h
  for (const geo of geos) {
    if (!timeLeft()) break;
    const m = (out.markets[geo] = { trending: [], rising: [], top: [] });
    try {
      const r = await fetchText(`https://trends.google.com/trending/rss?geo=${geo}`);
      if (r.status !== 200) { out.notes.push(`${geo} trending feed: HTTP ${r.status}`); continue; }
      for (const item of r.text.split(/<item>/i).slice(1)) {
        const news = item.split(/<ht:news_item>/i).slice(1).map(n => ({
          title: tag(n, 'ht:news_item_title'),
          url: tag(n, 'ht:news_item_url'),
          picture: tag(n, 'ht:news_item_picture'),
          source: tag(n, 'ht:news_item_source')
        })).filter(n => n.url);
        m.trending.push({
          topic: tag(item, 'title'),
          traffic: tag(item, 'ht:approx_traffic'),
          started: tag(item, 'pubDate'),
          picture: tag(item, 'ht:picture'),
          news
        });
      }
    } catch (e) { out.notes.push(`${geo} trending feed: ${e.message}`); }
  }

  // 2) Searches around "leather jacket", last 24h (best effort: Google rate limits this)
  let cookie = '';
  try {
    const home = await fetchText('https://trends.google.com/trends/?geo=US');
    cookie = [].concat(home.headers['set-cookie'] || []).map(c => String(c).split(';')[0]).join('; ');
  } catch (e) {}
  const trendsJson = async url => {
    const r = await fetchText(url, cookie ? { Cookie: cookie } : {});
    if (r.status === 429) throw Object.assign(new Error('Google rate limit (429), skipped this run'), { stop: true });
    if (r.status !== 200) throw new Error('HTTP ' + r.status);
    return JSON.parse(r.text.slice(r.text.indexOf('{')));
  };
  for (const geo of geos) {
    if (!timeLeft()) break;
    try {
      const req = { comparisonItem: [{ keyword: 'leather jacket', geo, time: 'now 1-d' }], category: 0, property: '' };
      const ex = await trendsJson('https://trends.google.com/trends/api/explore?hl=en-US&tz=0&req=' + encodeURIComponent(JSON.stringify(req)));
      const w = (ex.widgets || []).find(x => x.id === 'RELATED_QUERIES');
      if (!w) continue;
      const d = await trendsJson('https://trends.google.com/trends/api/widgetdata/relatedsearches?hl=en-US&tz=0&req=' + encodeURIComponent(JSON.stringify(w.request)) + '&token=' + w.token);
      const [top, rising] = (d.default?.rankedList || []).map(l => (l.rankedKeyword || []).map(k => ({ query: k.query, value: k.formattedValue })));
      out.markets[geo].top = (top || []).slice(0, 15);
      out.markets[geo].rising = (rising || []).slice(0, 15);
    } catch (e) {
      out.notes.push(`${geo} leather jacket searches: ${e.message}`);
      if (e.stop) break;
    }
  }

  // Best 5 topics around "leather jacket" for today's trend hunt
  const topicList = [];
  for (const m of Object.values(out.markets)) for (const r of [...m.rising, ...m.top]) topicList.push(r.query);
  out.topics = [...new Set(topicList.map(t => String(t).toLowerCase().trim()))]
    .filter(t => t && JACKET.test(t) && !NOT_WANTED.test(t)).slice(0, 5);

  // Extra search phrases for this hunt: rising first, then trending topics that are about jackets
  const phrases = [];
  for (const m of Object.values(out.markets)) {
    for (const r of m.rising) phrases.push(r.query);
    for (const t of m.trending) if (JACKET.test(t.topic)) phrases.push(t.topic);
    for (const r of m.top.slice(0, 3)) phrases.push(r.query);
  }
  out.trend_keywords = [...new Set(phrases.map(p => p.toLowerCase().trim()))]
    .filter(p => JACKET.test(p) && !NOT_WANTED.test(p))
    .map(p => /leather|suede|shearling/.test(p) ? p : p + ' leather')
    .slice(0, 6);

  // Hand the snapshot to the dashboard (it checks the news photos for leather jackets)
  try {
    await this.helpers.httpRequest({ url: dashboard + '/api/trends/ingest', method: 'POST', headers: { 'X-Ingestion-Key': KEY() }, body: out, json: true, timeout: 20000 });
  } catch (e) { out.notes.push('dashboard: ' + e.message); }

  await report(this.helpers, { run_id: String(body.runId || ''), dashboard_url: dashboard }, {
    step: 'Google Trends', status: 'done', count: out.topics.length,
    detail: (out.topics.length ? 'Top topics: ' + out.topics.join(', ') : 'No leather jacket topics in the last 24 hours') + (out.notes.length ? ' · ' + out.notes.join(' · ') : '')
  });
  return [{ json: { trend_keywords: out.trend_keywords, topics: out.topics, notes: out.notes, trending_topics: Object.values(out.markets).reduce((n, m) => n + m.trending.length, 0) } }];

function urlParts(value) {
  // n8n Code nodes have no URL class, so split URLs by hand
  const m = String(value || '').trim().match(/^(https?):\/\/([^\/?#:]+)(:\d+)?([^?#]*)/i);
  if (!m) return null;
  const host = m[2].toLowerCase();
  return { origin: m[1].toLowerCase() + '://' + host + (m[3] || ''), host, pathname: m[4] || '/' };
}

  // Reads hunt settings from the webhook body. Every field is optional.
  const body = $('Leather Hunt Webhook').first().json.body || {};
  const num = (v, d) => { const n = Number(v); return v !== '' && v !== null && v !== undefined && Number.isFinite(n) && n >= 0 ? n : d; };
  const list = v => (Array.isArray(v) ? v : String(v || '').split(/[\n,]/)).map(s => String(s).trim()).filter(Boolean);

  let minPrice = num(body.minPrice ?? body.priceRange?.min, 0);
  let maxPrice = num(body.maxPrice ?? body.priceRange?.max, 100000);
  if (minPrice > maxPrice) [minPrice, maxPrice] = [maxPrice, minPrice];

  const websites = [...new Set(list(body.websites)
    .map(w => /^https?:\/\//i.test(w) ? w : 'https://' + w)
    .map(w => urlParts(w)?.origin || '')
    .filter(Boolean))];

  const sources = list(body.sources).map(s => s.toLowerCase());
  const base = list(body.keywords);
  let trend = [];
  try { trend = $('Google Trends').first().json.trend_keywords || []; } catch (e) {}
  const celeb = list(body.trendKeywords).slice(0, 5);
  const keywords = base;
  const extra = [...new Set([...celeb, ...trend].map(k => k.toLowerCase()))];
  const markets = list(body.markets).map(m => m.toUpperCase()).filter(m => ['US', 'UK', 'CA'].includes(m));

  return [{ json: {
        min_price: minPrice,
    max_price: maxPrice,
    include_unpriced: body.includeUnpriced === true,
    allow_faux: body.allowFaux === true,
    keywords: [...new Set([...extra, ...(keywords.length ? keywords : [
      "women's leather jacket", "men's leather jacket", 'leather biker jacket', 'leather bomber jacket',
      'leather moto jacket', 'shearling leather jacket', 'vintage leather jacket', 'suede leather jacket'
    ])])].slice(0, 14),
    trend_keywords: extra,
    mode: body.mode === 'trend' ? 'trend' : 'normal',
    serper_key: String(body.serperKey || ''),
    markets: markets.length ? markets : ['US', 'UK', 'CA'],
    sources: body.mode === 'trend' ? ['google_shopping'] : sources.length ? sources : ['ebay', 'etsy', 'websites'],
    websites,
    per_query_limit: Math.min(num(body.perQueryLimit, 25), 50),
    max_pages_per_site: Math.min(num(body.maxPagesPerSite, 30), 300),
    top_n: body.mode === 'trend' ? 50 : Math.max(1, Math.min(num(body.topN, 10), 100)),
    run_id: String(body.runId || ''),
    dashboard_url: String(body.dashboardUrl || 'http://leather-hunt:4300').replace(/\/+$/, ''),
    started_at: new Date().toISOString()
  }}];

// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
function isLeatherJacket(text, allowFaux) {
  const t = String(text || '').toLowerCase().replace(/%20|[-_/+]+/g, ' ');
  if (!/\bleather\b|\bsuede\b|\bshearling\b|\bnappa\b|\blambskin\b|\bcowhide\b/.test(t)) return false;
  if (!/\b(jacket|jackets|bomber|biker|moto|motorcycle|racer|trucker|aviator|blouson|shacket)\b/.test(t)) return false;
  // other products that mention leather jackets (a jacket "with belt", a "shirt jacket" or "wool lining" still counts)
  if (/\b(vest|waistcoat|gilet|pants|trousers|skirt|chaps|pattern|pdf|patch|patches|sticker|keychain|keyring|key ring|wallet|bag|purse|gloves|boots|shoes|hanger|cleaner|conditioner|toy|doll|barbie|dog|helmet|lot of|bundle|phone case|case for|earring|earrings|necklace|magnet|ornament|miniature)\b/.test(t)) return false;
  if (/\b(overcoat|trench|duster|parka|peacoat|tuxedo|suit|suits|turtleneck|sweater|hoodie only)\b/.test(t)) return false;
  if (/\b(coat|coats)\b/.test(t) && !/\bjackets?\b/.test(t)) return false;
  if (!allowFaux && /\b(faux|vegan|pu leather|pleather|leatherette|imitation|synthetic leather)\b/.test(t)) return false;
  return true;
}

function inPriceRange(price, cfg) {
  const p = Number(price);
  if (!Number.isFinite(p) || p <= 0) return cfg.include_unpriced === true;
  return p >= cfg.min_price && p <= cfg.max_price;
}

function httpsImages(values) {
  return [...new Set(values.flat(Infinity).map(v => typeof v === 'string' ? v : (v && (v.imageUrl || v.url_fullxfull || v.url_570xN || v.contentUrl || v.url || v.src)) || '')
    .map(v => String(v || '').trim().replace(/&amp;/g, '&').replace(/^\/\//, 'https://').replace(/^http:\/\//i, 'https://'))
    .filter(v => /^https:\/\//i.test(v))
    .filter(v => !/\.(gif|svg)(\?|$)/i.test(v))
    .filter(v => !/(placeholder|no[-_ ]?image|logo|favicon|sprite|icon|avatar|pixel|size[-_ ]?chart|payment|badge)/i.test(v)))];
}

async function report(helpers, cfg, body) {
  // Tells the dashboard how the hunt is going. Never stops the hunt if the dashboard can't be reached.
  if (!cfg || !cfg.run_id || !cfg.dashboard_url) return;
  try {
    await helpers.httpRequest({ url: cfg.dashboard_url + '/api/hunt/progress', method: 'POST', headers: { 'X-Ingestion-Key': KEY() }, body: { runId: cfg.run_id, ...body }, json: true, timeout: 5000 });
  } catch (e) {}
}

  // Today's trend hunt only: the 5 best "leather jacket" topics from Google Trends,
  // each searched on Google Shopping, first 10 leather jackets per topic.
  // Google Shopping results come from Serper.dev.
  const c = $('Hunt Config').first().json;
  if (c.mode !== 'trend') return [];
  if (!c.serper_key) throw new Error('Today\'s trend hunt needs a Serper key - add it in Hunt settings');
  let topics = [];
  try { topics = $('Google Trends').first().json.topics || []; } catch (e) {}
  if (!topics.length) topics = ['leather jacket'];
  const PER_TOPIC = 10;
  const helpers = this.helpers;
  const started = Date.now();
  const out = [];
  const notes = [];
  const priceNum = v => { const n = typeof v === 'number' ? v : Number(String(v || '').replace(/[^0-9.]/g, '')); return Number.isFinite(n) && n > 0 ? n : null; };

  // Each provider returns results in one shape: { title, link, price, store, images, rating, reviews, id, snippet }
  const providers = [];
  if (c.serper_key) providers.push({ name: 'Serper', async search(q) {
    const d = await helpers.httpRequest({ url: 'https://google.serper.dev/shopping', method: 'POST', headers: { 'X-API-KEY': c.serper_key, 'Content-Type': 'application/json' }, body: { q, gl: 'us', hl: 'en', num: 40 }, json: true, timeout: 20000 });
    if (d.message && !d.shopping) throw new Error(d.message);
    return (d.shopping || []).map(r => ({ title: r.title, link: r.link, price: priceNum(r.price), store: r.source,
      images: [r.imageUrl], rating: r.rating, reviews: r.ratingCount, id: r.productId, snippet: r.delivery || '' }));
  } });

  for (const topic of topics.slice(0, 5)) {
    if (Date.now() - started > 45000) { notes.push('time limit reached'); break; }
    let results = null;
    for (const p of providers) {
      if (p.out) continue;
      try { results = await p.search(topic); notes.push(`${topic}: ${p.name}`); break; }
      catch (e) {
        const msg = String(e.message || e);
        notes.push(`${topic}: ${p.name} failed (${msg.slice(0, 120)})`);
        // out of searches / bad key / rate limited: don't try this provider again this run
        if (/run out|limit|quota|credits|401|403|429|invalid api key|unauthor/i.test(msg)) p.out = true;
      }
    }
    if (!results) continue;
    let kept = 0;
    results.forEach((r, i) => {
      if (kept >= PER_TOPIC) return;
      const name = String(r.title || '').trim();
      if (!name || !r.link) return;
      if (!isLeatherJacket(name, c.allow_faux)) return;
      if (!inPriceRange(r.price, c)) return;
      const images = httpsImages(r.images);
      if (!images.length) return;
      kept++;
      out.push({ json: {
        source: 'google_shopping',
        marketplace: 'Google Shopping',
        source_domain: String(r.store || ''),
        product_id: String(r.productId || r.id || r.link),
        product_name: name,
        product_link: r.link,
        source_price: r.price,
        source_currency: 'USD',
        image_urls: images,
        seller_name: String(r.store || ''),
        rating: Number(r.rating) || null,
        review_count: Number(r.reviews) || null,
        search_rank: kept,
        search_query: topic,
        trend_topic: topic,
        market: 'US',
        description: r.snippet || '',
        raw_details: { tags: ['Google Trends: ' + topic], localizedAspects: [{ name: 'Trending topic', value: topic }, ...(r.delivery ? [{ name: 'Delivery', value: String(r.delivery) }] : [])] }
      } });
    });
    if (!kept) notes.push(`${topic}: no leather jackets in the price range`);
  }
  await report(helpers, c, { step: 'Google Shopping', status: out.length ? 'done' : 'error', count: out.length,
    detail: out.length ? `${out.length} jackets from ${new Set(out.map(o => o.json.trend_topic)).size} topics` : 'No Google Shopping jackets found · ' + notes.slice(0, 3).join(' · ') });
  if (!out.length) out.push({ json: { kind: 'notice', origin: 'Google Shopping', requests: notes, reason: 'No Google Shopping jackets found' } });
  return out;

const c = $('Hunt Config').first().json;
if (!c.sources.includes('ebay')) return [];
const token = $input.first().json.access_token;
if (!token) throw new Error('eBay OAuth token missing - check the Ebay credential');

const currency = { US: 'USD', UK: 'GBP', CA: 'CAD' };
const geo = { US: 'US', UK: 'GB', CA: 'CA' };
const marketplaceId = { US: 'EBAY_US', UK: 'EBAY_GB', CA: 'EBAY_CA' };
const out = [];

for (const market of c.markets) {
  for (const keyword of c.keywords) {
    out.push({ json: {
      query: keyword,
      market,
      geo: geo[market],
      currency: currency[market],
      marketplace_id: marketplaceId[market],
      // Price range is applied natively by eBay in the market's own currency
      filter: `price:[${c.min_price}..${c.max_price}],priceCurrency:${currency[market]},deliveryCountry:${geo[market]}`,
      limit: c.per_query_limit,
      access_token: token
    }});
  }
}
return out;

function isLeatherJacket(text, allowFaux) {
  const t = String(text || '').toLowerCase().replace(/%20|[-_/+]+/g, ' ');
  if (!/\bleather\b|\bsuede\b|\bshearling\b|\bnappa\b|\blambskin\b|\bcowhide\b/.test(t)) return false;
  if (!/\b(jacket|jackets|bomber|biker|moto|motorcycle|racer|trucker|aviator|blouson|shacket)\b/.test(t)) return false;
  // other products that mention leather jackets (a jacket "with belt", a "shirt jacket" or "wool lining" still counts)
  if (/\b(vest|waistcoat|gilet|pants|trousers|skirt|chaps|pattern|pdf|patch|patches|sticker|keychain|keyring|key ring|wallet|bag|purse|gloves|boots|shoes|hanger|cleaner|conditioner|toy|doll|barbie|dog|helmet|lot of|bundle|phone case|case for|earring|earrings|necklace|magnet|ornament|miniature)\b/.test(t)) return false;
  if (/\b(overcoat|trench|duster|parka|peacoat|tuxedo|suit|suits|turtleneck|sweater|hoodie only)\b/.test(t)) return false;
  if (/\b(coat|coats)\b/.test(t) && !/\bjackets?\b/.test(t)) return false;
  if (!allowFaux && /\b(faux|vegan|pu leather|pleather|leatherette|imitation|synthetic leather)\b/.test(t)) return false;
  return true;
}

function inPriceRange(price, cfg) {
  const p = Number(price);
  if (!Number.isFinite(p) || p <= 0) return cfg.include_unpriced === true;
  return p >= cfg.min_price && p <= cfg.max_price;
}

function httpsImages(values) {
  return [...new Set(values.flat(Infinity).map(v => typeof v === 'string' ? v : (v && (v.imageUrl || v.url_fullxfull || v.url_570xN || v.contentUrl || v.url || v.src)) || '')
    .map(v => String(v || '').trim().replace(/&amp;/g, '&').replace(/^\/\//, 'https://').replace(/^http:\/\//i, 'https://'))
    .filter(v => /^https:\/\//i.test(v))
    .filter(v => !/\.(gif|svg)(\?|$)/i.test(v))
    .filter(v => !/(placeholder|no[-_ ]?image|logo|favicon|sprite|icon|avatar|pixel|size[-_ ]?chart|payment|badge)/i.test(v)))];
}

  const c = $('Hunt Config').first().json;
  const queries = $('eBay Query Builder').all();
  const seen = new Set();
  const out = [];

  $input.all().forEach((item, i) => {
    const ctx = queries[item.pairedItem?.item ?? i]?.json || {};
    const list = Array.isArray(item.json.itemSummaries) ? item.json.itemSummaries : [];

    list.forEach((s, index) => {
      const id = String(s.legacyItemId || s.itemId || '');
      if (!id || seen.has(id)) return;
      if (!isLeatherJacket(s.title, c.allow_faux)) return;
      const price = Number(s.price?.value);
      if (!inPriceRange(price, c)) return;
      seen.add(id);

      out.push({ json: {
        source: 'ebay',
        marketplace: 'eBay',
        source_domain: 'ebay.com',
        product_id: id,
        item_id: s.itemId,
        product_name: s.title,
        product_link: String(s.itemWebUrl || '').split('?')[0],
        source_price: Number.isFinite(price) ? price : null,
        source_currency: s.price?.currency || ctx.currency || 'USD',
        image_urls: httpsImages([s.image || {}, s.additionalImages || [], s.thumbnailImages || []]),
        description: s.shortDescription || '',
        condition: s.condition || '',
        seller_name: s.seller?.username || '',
        seller_feedback: Number(s.seller?.feedbackPercentage || 0),
        seller_feedback_score: Number(s.seller?.feedbackScore || 0),
        market: ctx.market || 'US',
        marketplace_id: ctx.marketplace_id || 'EBAY_US',
        search_query: ctx.query || '',
        search_rank: index + 1,
        raw_details: {
          itemId: s.itemId,
          legacyItemId: s.legacyItemId,
          buyingOptions: s.buyingOptions || [],
          categories: s.categories || [],
          itemLocation: s.itemLocation || {},
          shippingOptions: s.shippingOptions || [],
          itemCreationDate: s.itemCreationDate || null
        }
      }});
    });
  });
  return out;

function httpsImages(values) {
  return [...new Set(values.flat(Infinity).map(v => typeof v === 'string' ? v : (v && (v.imageUrl || v.url_fullxfull || v.url_570xN || v.contentUrl || v.url || v.src)) || '')
