  const m = String(value || '').trim().match(/^(https?):\/\/([^\/?#:]+)(:\d+)?([^?#]*)/i);
  if (!m) return null;
  const host = m[2].toLowerCase();
  return { origin: m[1].toLowerCase() + '://' + host + (m[3] || ''), host, pathname: m[4] || '/' };
