function makeGet(helpers, deadline = Date.now() + 50000) {
  // Fetch with block detection. n8n Code nodes are limited to 60s, so timeouts stay short.
  const BLOCK = /sgcaptcha|challenge-platform|cf-chl|cf_chl|sucuri_cloudproxy|Just a moment\.\.\.|Attention Required/i;
  const blockName = t => /sgcaptcha/i.test(t) ? 'SiteGround CAPTCHA' : /sucuri/i.test(t) ? 'Sucuri firewall' : 'Cloudflare challenge';
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const log = [];
  const note = (url, result) => { log.push(url.replace(/^https?:\/\/[^\/]+/, '') + ' -> ' + result); return log.length; };
  async function get(url, json = false, timeout = 12000) {
    for (let attempt = 0; attempt < 2; attempt++) {
      // never run past n8n's 60 s limit: shorter timeout near the end, nothing new when time is up
      const left = deadline - Date.now();
      if (left < 3000) return { status: 0, skipped: 'out of time' };
      timeout = Math.min(timeout, left - 1500);
      try {
        // Plain request, same as n8n's HTTP Request node (no browser User-Agent)
        const res = await helpers.httpRequest({ url, method: 'GET', timeout });
        const text = typeof res === 'string' ? res : (Buffer.isBuffer(res) ? res.toString('utf8') : null);
        if (text && BLOCK.test(text.slice(0, 4000))) { note(url, 'blocked: ' + blockName(text)); return { blocked: blockName(text) }; }
        note(url, 'ok ' + (text !== null ? text.length + ' chars' + (/<urlset|<sitemapindex/i.test(text.slice(0, 600)) ? ' (sitemap)' : /^\s*[\[{]/.test(text) ? ' (json)' : /<html/i.test(text.slice(0, 600)) ? ' (html)' : '') : 'object'));
        if (json) {
          if (text === null) return { data: res };
          try { return { data: JSON.parse(text) }; } catch { return {}; }
        }
        return { text: text !== null ? text : JSON.stringify(res) };
      } catch (e) {
        const status = Number(e.httpCode || e.statusCode || e.response?.status || e.cause?.response?.status || e.cause?.status || (String(e.message || '').match(/status code (\d{3})/) || [])[1] || 0);
        const body = String(e.response?.body || e.response?.data || e.cause?.response?.data || e.description || '');
        note(url, (status ? 'HTTP ' + status : 'error') + ' ' + String(e.message || '').slice(0, 80));
        if (BLOCK.test(body.slice(0, 4000))) return { blocked: blockName(body) };
        if (status === 403 && attempt === 1) return { blocked: 'HTTP 403 Forbidden (firewall)' };
        if (attempt === 0 && [403, 429, 503].includes(status) && deadline - Date.now() > 15000) { await wait(3000); continue; }
        return { status };
      }
    }
    return {};
  }
  get.log = log;
  return get;
}

