    if (!p.product_name || !p.product_link || !inPriceRange(p.source_price, c)) return;
    if (!isLeatherJacket(p.product_name, c.allow_faux)) return;
    p.image_urls = httpsImages([p.image_urls]).slice(0, 30);
    if (!p.image_urls.length) return;
    const hash = sha256(canonicalUrl(p.product_link));
    if (seen.has(hash)) return;
    seen.add(hash);
    out.push({ ...base, ...p, kind: 'product', product_id: hash, url_hash: hash });
  }

  // 0) Homepage first: tells us the platform, so we don't waste time on APIs the site doesn't have
  const homePage = await get(origin + '/');
  if (homePage.blocked) blocked = homePage.blocked;
  const homeHtml = String(homePage.text || '');
  let isShopify = /cdn\.shopify\.com|Shopify\.theme|myshopify\.com/i.test(homeHtml);
  let firstShopifyPage = null;
  if (isShopify && !blocked) {
    firstShopifyPage = await get(`${origin}/products.json?limit=250&page=1`, true);
    if (firstShopifyPage.blocked) blocked = firstShopifyPage.blocked;
    if (!Array.isArray(firstShopifyPage.data?.products)) isShopify = false;
  }
  const isWoo = /wp-content|woocommerce|wp-json/i.test(homeHtml);

  // 1) Shopify: best-seller collection + newest products (products.json is newest first)
  const shopifyBest = new Set();
  if (isShopify && !blocked) for (const handle of ['best-sellers', 'bestsellers', 'best-selling', 'best-seller', 'top-sellers', 'popular']) {
    if (!timeLeft()) break;
    if (!timeLeft()) break;
    const r = await get(`${origin}/collections/${handle}/products.json?limit=250`, true);
    if (r.blocked) { blocked = r.blocked; break; }
    const list = Array.isArray(r.data?.products) ? r.data.products : [];
    list.forEach(p => shopifyBest.add(p.handle));
    if (list.length) break;
  }
  for (let page = 1; isShopify && page <= 4 && timeLeft() && !blocked; page++) {
    const r = page === 1 && firstShopifyPage ? firstShopifyPage : await get(`${origin}/products.json?limit=250&page=${page}`, true);
    if (r.blocked) { blocked = r.blocked; break; }
    const list = Array.isArray(r.data?.products) ? r.data.products : null;
    if (!list || !list.length) break;
    if (page === 1) {
      const cart = await get(`${origin}/cart.js`, true);
      base.currency = cart.data?.currency || 'USD';
    }
    for (const sp of list) {
      const variants = sp.variants || [];
      const prices = variants.map(v => Number(v.price)).filter(n => Number.isFinite(n) && n > 0);
      const compare = variants.map(v => Number(v.compare_at_price)).filter(n => Number.isFinite(n) && n > 0);
      addProduct({
        product_name: decodeHtml(sp.title),
        product_link: `${origin}/products/${sp.handle}`,
        source_price: prices.length ? Math.min(...prices) : null,
        source_currency: base.currency,
        image_urls: (sp.images || []).map(i => i.src),
        description: stripHtml(sp.body_html),
        brand: decodeHtml(sp.vendor || ''),
        is_bestseller: shopifyBest.has(sp.handle),
        listed_at: sp.published_at || sp.created_at || null,
        raw_details: {
          platform: 'shopify',
          sku: variants[0]?.sku || '',
          availability: variants.some(v => v.available) ? 'InStock' : 'OutOfStock',
          tags: Array.isArray(sp.tags) ? sp.tags : String(sp.tags || '').split(',').map(t => t.trim()).filter(Boolean),
          localizedAspects: [
            ...(sp.options || []).map(o => ({ name: o.name, value: (o.values || []).join(', ') })),
            ...(sp.product_type ? [{ name: 'Type', value: sp.product_type }] : []),
            ...(compare.length ? [{ name: 'Compare at price', value: String(Math.max(...compare)) }] : [])
          ]
        }
      });
    }
    if (list.length < 250) break;
  }

  // 2) WooCommerce Store API: most popular + newest
  if (isWoo && !out.length && !blocked) {
    const wooBest = new Set();
    const popular = await get(`${origin}/wp-json/wc/store/v1/products?per_page=30&orderby=popularity&order=desc`, true);
    if (popular.blocked) blocked = popular.blocked;
    const lists = [];
    if (Array.isArray(popular.data)) { popular.data.forEach(p => wooBest.add(p.id)); lists.push(popular.data); }
    if (!blocked && timeLeft()) {
      const newest = await get(`${origin}/wp-json/wc/store/v1/products?per_page=100&orderby=date&order=desc`, true);
      if (Array.isArray(newest.data)) lists.push(newest.data);
    }
    for (const wp of lists.flat()) {
      const pr = wp.prices || {};
      const price = Number(pr.price) / Math.pow(10, Number(pr.currency_minor_unit ?? 2));
      addProduct({
        product_name: decodeHtml(wp.name),
        product_link: wp.permalink,
        source_price: Number.isFinite(price) && price > 0 ? price : null,
        source_currency: pr.currency_code || 'USD',
        image_urls: (wp.images || []).map(i => i.src),
        description: stripHtml(wp.description || wp.short_description),
        brand: (wp.brands || [])[0]?.name || '',
        rating: Number(wp.average_rating || 0),
        review_count: Number(wp.review_count || 0),
        is_bestseller: wooBest.has(wp.id),
        listed_at: wp.date_created || null,
        raw_details: {
          platform: 'woocommerce',
          sku: wp.sku || '',
          availability: wp.is_in_stock ? 'InStock' : 'OutOfStock',
          tags: (wp.tags || []).map(t => decodeHtml(t.name)),
          localizedAspects: (wp.attributes || []).map(a => ({ name: decodeHtml(a.name), value: (a.terms || []).map(t => decodeHtml(t.name)).join(', ') }))
        }
      });
    }
  }

  // 3) Other sites: best-seller page(s) from the homepage + newest products from the sitemap (lastmod)
  if (!out.length && !blocked) {
    const locs = xml => [...String(xml).matchAll(/<loc>\s*(?:<!\[CDATA\[)?\s*([^<\]]+?)\s*(?:\]\]>)?\s*<\/loc>/gi)].map(m => decodeHtml(m[1]));
    const NOT_PRODUCT = /\/(collections?|category|categories|product-category|tag|tags|pages?|blogs?|news|articles?|author|search|cart|account|checkout|contact|about|faq|policies|policy|wishlist|compare)(\/|$)|best[-_ ]?sellers?|top[-_ ]?sellers?|new[-_ ]?arrivals?|\/sale\/?$/i;
    const LOOKS_PRODUCT = /\/(products?|product-page|item|items|p|pd|dp|shop|store|buy|catalog\/product\/view)\/[^/]+|\/[^/]+\.html?$|[?&](product_id|route=product\/product|id_product)=|-p-?\d+(\.html)?$|\/\d+-[a-z0-9-]+\.html$/i;
    const NEW = /new[-_ ]?arrivals?|new[-_ ]?in\b|just[-_ ]?in|latest|newest/i;
    const host = urlParts(origin).host;
    const absolute = href => {
      const h = decodeHtml(href).trim();
      if (/^https?:\/\//i.test(h)) return h;
      if (h.startsWith('//')) return 'https:' + h;
      if (h.startsWith('/')) return origin + h;
      return '';
    };

    // Sitemap: product URL -> { images, lastmod }
    const roots = [];
    const robots = await get(origin + '/robots.txt');
    if (robots.blocked) blocked = robots.blocked;
    if (robots.text) for (const m of robots.text.matchAll(/^\s*sitemap:\s*(\S+)/gim)) roots.push(m[1].trim());
    if (!roots.length) roots.push(origin + '/sitemap.xml', origin + '/sitemap_index.xml', origin + '/product-sitemap.xml', origin + '/xmlsitemap.php', origin + '/sitemap_products_1.xml', origin + '/wp-sitemap.xml');
    const queue = [...new Set(roots)].map(url => ({ url, product: /product/i.test(url) }));
    const visited = new Set();
    const fromProductMaps = new Map();
    const fromOtherMaps = new Map();
    while (queue.length && visited.size < 15 && timeLeft() && !blocked) {
      const sm = queue.shift();
      if (visited.has(sm.url) || /\.gz(\?|$)/i.test(sm.url)) continue;
      visited.add(sm.url);
      const r = await get(sm.url);
      if (r.blocked) { blocked = r.blocked; break; }
      const xml = r.text || '';
      if (/<sitemapindex/i.test(xml)) {
        const children = locs(xml);
        const productMaps = children.filter(u => /product/i.test(u));
        const useful = productMaps.length ? productMaps : children.filter(u => !/(post|page|blog|article|author|tag|categor|collection|image|video|news)/i.test(u));
        queue.unshift(...useful.map(url => ({ url, product: /product/i.test(url) })));
      } else if (/<urlset/i.test(xml)) {
        for (const block of xml.split(/<url>/i).slice(1)) {
          const u = (locs(block)[0] || '').split('#')[0];
          const path = urlParts(u)?.pathname || '/';
          if (!/^https?:\/\//i.test(u) || path === '/' || NOT_PRODUCT.test(path)) continue;
          const images = [...block.matchAll(/<image:loc>\s*(?:<!\[CDATA\[)?\s*([^<\]]+?)\s*(?:\]\]>)?\s*<\/image:loc>/gi)].map(m => decodeHtml(m[1]));
          const lastmod = (block.match(/<lastmod>\s*([^<]+?)\s*<\/lastmod>/i) || [])[1] || null;
          (sm.product ? fromProductMaps : fromOtherMaps).set(u, { images, lastmod });
        }
      }
    }
    const catalog = fromProductMaps.size ? fromProductMaps : new Map([...fromOtherMaps].filter(([u]) => LOOKS_PRODUCT.test(u)));

    // Listing pages linked from the homepage: best sellers + new arrivals. Cards labelled "Best Seller" count too.
    const bestUrls = [], newUrls = [], catUrls = [];
    const productLinks = html => {
      const res = [];
      const hits = [...String(html).matchAll(/href=["']([^"'#]+)["']/gi)];
      hits.forEach((m, i) => {
        const u0 = absolute(m[1]); const u = /[?&](product_id|id_product|route=product)/i.test(u0) ? u0.replace(/&amp;/g, '&') : u0.split('?')[0];
        if (!u || urlParts(u)?.host !== host) return;
        const path = urlParts(u)?.pathname || '/';
        if (path === '/' || NOT_PRODUCT.test(path)) return;
        const known = [...catalog.keys()].find(k => canonicalUrl(k) === canonicalUrl(u));
        if (!known && !LOOKS_PRODUCT.test(u)) return;
        const next = hits.slice(i + 1).find(n => absolute(n[1]).split('?')[0] !== u);
        const card = String(html).slice(m.index, next ? next.index : m.index + 3000);
        const labelled = /best[-_ ]?seller/i.test(card.replace(/href=["'][^"']*["']/gi, ''));
        res.push({ url: known || u, labelled });
      });
      return res;
    };
    if (!blocked && timeLeft()) {
      const home = homePage;
      const links = [...new Set([...String(home.text || '').matchAll(/href=["']([^"'#]+)["']/gi)].map(m => absolute(m[1]))
        .filter(u => u && urlParts(u)?.host === host))];
      productLinks(home.text || '').forEach(p => { if (p.labelled) bestUrls.push(p.url); });
      const lists = [
        ...links.filter(u => BEST.test(u)).slice(0, 2).map(u => ({ u, best: true })),
        ...links.filter(u => NEW.test(u) && !BEST.test(u)).slice(0, 1).map(u => ({ u, best: false })),
        ...links.filter(u => !BEST.test(u) && !NEW.test(u) && !LOOKS_PRODUCT.test(u) && /jacket|leather|biker|bomber|moto|shearling|suede|men|women/i.test(urlParts(u)?.pathname || '') && !/coat|blazer|suit|tux|wool|vest|bag|wallet|glove|shoe|boot/i.test(urlParts(u)?.pathname || ''))
          .slice(0, catalog.size ? 0 : 3).map(u => ({ u, best: false, cat: true }))
      ];
      for (const l of lists) {
        if (!timeLeft() || blocked) break;
        const r = await get(l.u);
        if (r.blocked) { blocked = r.blocked; break; }
        for (const p of productLinks(r.text || '')) (l.best || p.labelled ? bestUrls : l.cat ? catUrls : newUrls).push(p.url);
      }
    }

    // Order: best sellers first, then newest by lastmod; leather jackets only
    const isJacketUrl = u => isLeatherJacket('leather ' + decodeURIComponent(urlParts(u)?.pathname || ''), c.allow_faux);
    const newest = [...catalog].sort((a, b) => String(b[1].lastmod || '').localeCompare(String(a[1].lastmod || ''))).map(([u]) => u);
    const bestSet = new Set(bestUrls.map(canonicalUrl));
    for (const url of [...new Set([...bestUrls, ...newUrls, ...newest, ...catUrls])]) {
      if (out.length >= c.max_pages_per_site) break;
      if (!isJacketUrl(url)) continue;
      const hash = sha256(canonicalUrl(url));
      if (seen.has(hash)) continue;
      seen.add(hash);
      const info = catalog.get(url) || {};
      out.push({ kind: 'page', origin, url, sitemap_images: info.images || [], listed_at: info.lastmod || (newUrls.includes(url) ? new Date().toISOString() : null), is_bestseller: bestSet.has(canonicalUrl(url)), url_hash: hash });
    }
  }

  if (!out.length) out.push({ kind: 'notice', origin, requests: get.log.slice(0, 30), reason: blocked ? `${blocked} - whitelist the n8n server IP in the site firewall` : 'No products, product feed or sitemap found' });
  const notice = out.find(o => o.kind === 'notice');
  await report(this.helpers, c, { step: 'Website · ' + (urlParts(origin)?.host || origin), status: notice ? 'error' : 'done', count: out.length - (notice ? 1 : 0),
    detail: notice ? origin + ': ' + notice.reason : `${out.length} jackets / product pages found (best sellers + newest)` });
  return out.map(json => ({ json }));

// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
function inPriceRange(price, cfg) {
  const p = Number(price);
  if (!Number.isFinite(p) || p <= 0) return cfg.include_unpriced === true;
  return p >= cfg.min_price && p <= cfg.max_price;
}

function httpsImages(values) {
  return [...new Set(values.flat(Infinity).map(v => typeof v === 'string' ? v : (v && (v.imageUrl || v.url_fullxfull || v.url_570xN || v.contentUrl || v.url || v.src)) || '')
    .map(v => String(v || '').trim().replace(/&amp;/g, '&').replace(/^\/\//, 'https://').replace(/^http:\/\//i, 'https://'))
    .filter(v => /^https:\/\//i.test(v))
    .filter(v => !/\.(gif|svg)(\?|$)/i.test(v))
    .filter(v => !/(placeholder|no[-_ ]?image|logo|favicon|sprite|icon|avatar|pixel|size[-_ ]?chart|payment|badge)/i.test(v)))];
}

function sha256(input) {
  // Pure JS SHA-256 (n8n blocks require('crypto') by default)
  const bytes = unescape(encodeURIComponent(String(input)));
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const words = [];
  for (let i = 0; i < l; i++) words[i >> 2] |= bytes.charCodeAt(i) << (24 - (i % 4) * 8);
  words[l >> 2] |= 0x80 << (24 - (l % 4) * 8);
  words[(((l + 8) >> 6) + 1) * 16 - 1] = l * 8;
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let j = 0; j < words.length; j += 16) {
    const w = Array.from({ length: 16 }, (_, k) => words[j + k] | 0);
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      if (i >= 16) {
        const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);
        const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
        w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      }
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

function urlParts(value) {
  // n8n Code nodes have no URL class, so split URLs by hand
  const m = String(value || '').trim().match(/^(https?):\/\/([^\/?#:]+)(:\d+)?([^?#]*)/i);
  if (!m) return null;
  const host = m[2].toLowerCase();
  return { origin: m[1].toLowerCase() + '://' + host + (m[3] || ''), host, pathname: m[4] || '/' };
}

function makeGet(helpers, deadline = Date.now() + 50000) {
  // Fetch with block detection. n8n Code nodes are limited to 60s, so timeouts stay short.
  const BLOCK = /sgcaptcha|challenge-platform|cf-chl|cf_chl|sucuri_cloudproxy|Just a moment\.\.\.|Attention Required/i;
  const blockName = t => /sgcaptcha/i.test(t) ? 'SiteGround CAPTCHA' : /sucuri/i.test(t) ? 'Sucuri firewall' : 'Cloudflare challenge';
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const log = [];
  const note = (url, result) => { log.push(url.replace(/^https?:\/\/[^\/]+/, '') + ' -> ' + result); return log.length; };
  async function get(url, json = false, timeout = 12000) {
    for (let attempt = 0; attempt < 2; attempt++) {
      // never run past n8n's 60 s limit: shorter timeout near the end, nothing new when time is up
      const left = deadline - Date.now();
      if (left < 3000) return { status: 0, skipped: 'out of time' };
      timeout = Math.min(timeout, left - 1500);
      try {
        // Plain request, same as n8n's HTTP Request node (no browser User-Agent)
        const res = await helpers.httpRequest({ url, method: 'GET', timeout });
        const text = typeof res === 'string' ? res : (Buffer.isBuffer(res) ? res.toString('utf8') : null);
        if (text && BLOCK.test(text.slice(0, 4000))) { note(url, 'blocked: ' + blockName(text)); return { blocked: blockName(text) }; }
        note(url, 'ok ' + (text !== null ? text.length + ' chars' + (/<urlset|<sitemapindex/i.test(text.slice(0, 600)) ? ' (sitemap)' : /^\s*[\[{]/.test(text) ? ' (json)' : /<html/i.test(text.slice(0, 600)) ? ' (html)' : '') : 'object'));
        if (json) {
          if (text === null) return { data: res };
          try { return { data: JSON.parse(text) }; } catch { return {}; }
        }
        return { text: text !== null ? text : JSON.stringify(res) };
      } catch (e) {
        const status = Number(e.httpCode || e.statusCode || e.response?.status || e.cause?.response?.status || e.cause?.status || (String(e.message || '').match(/status code (\d{3})/) || [])[1] || 0);
        const body = String(e.response?.body || e.response?.data || e.cause?.response?.data || e.description || '');
        note(url, (status ? 'HTTP ' + status : 'error') + ' ' + String(e.message || '').slice(0, 80));
        if (BLOCK.test(body.slice(0, 4000))) return { blocked: blockName(body) };
        if (status === 403 && attempt === 1) return { blocked: 'HTTP 403 Forbidden (firewall)' };
        if (attempt === 0 && [403, 429, 503].includes(status) && deadline - Date.now() > 15000) { await wait(3000); continue; }
        return { status };
      }
    }
    return {};
  }
  get.log = log;
  return get;
}

function decodeHtml(s) {
  return String(s || '').replace(/&amp;/g, '&').replace(/&#39;|&#039;|&#8217;/g, "'").replace(/&quot;/g, '"').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&nbsp;/g, ' ').replace(/&#8211;/g, '-').trim();
}

function stripHtml(html) {
  return decodeHtml(String(html || '').replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, ' ').replace(/<br\s*\/?>|<\/p>|<\/li>/gi, '\n').replace(/<[^>]+>/g, ' ')).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim().slice(0, 6000);
}

function canonicalUrl(url) {
  // lowercase host, no www, no query/hash, no trailing slash, no /collections/x/ prefix
  const u = urlParts(url);
  if (!u) return String(url).toLowerCase();
  const path = u.pathname.replace(/\/collections\/[^/]+(?=\/products\/)/i, '').replace(/\/+$/, '').toLowerCase();
  return u.host.replace(/^www\./, '') + path;
}

function siteBase(origin) {
  const domain = urlParts(origin).host.replace(/^www\./, '');
  return { source: 'website', marketplace: 'Website', source_domain: domain, seller_name: domain, market: '', search_query: 'full catalog', condition: 'New' };
}

function isLeatherJacket(text, allowFaux) {
  const t = String(text || '').toLowerCase().replace(/%20|[-_/+]+/g, ' ');
  if (!/\bleather\b|\bsuede\b|\bshearling\b|\bnappa\b|\blambskin\b|\bcowhide\b/.test(t)) return false;
  if (!/\b(jacket|jackets|bomber|biker|moto|motorcycle|racer|trucker|aviator|blouson|shacket)\b/.test(t)) return false;
  // other products that mention leather jackets (a jacket "with belt", a "shirt jacket" or "wool lining" still counts)
  if (/\b(vest|waistcoat|gilet|pants|trousers|skirt|chaps|pattern|pdf|patch|patches|sticker|keychain|keyring|key ring|wallet|bag|purse|gloves|boots|shoes|hanger|cleaner|conditioner|toy|doll|barbie|dog|helmet|lot of|bundle|phone case|case for|earring|earrings|necklace|magnet|ornament|miniature)\b/.test(t)) return false;
  if (/\b(overcoat|trench|duster|parka|peacoat|tuxedo|suit|suits|turtleneck|sweater|hoodie only)\b/.test(t)) return false;
  if (/\b(coat|coats)\b/.test(t) && !/\bjackets?\b/.test(t)) return false;
  if (!allowFaux && /\b(faux|vegan|pu leather|pleather|leatherette|imitation|synthetic leather)\b/.test(t)) return false;
  return true;
}

  // 6 product pages per run (Loop Over Product Pages) so each run stays well under n8n's 60s limit
  const c = $('Hunt Config').first().json;
  if (await shouldStop(this.helpers)) return [];
  const get = makeGet(this.helpers, Date.now() + 52000);
  const wait = ms => new Promise(r => setTimeout(r, ms));
  const out = [];

  function findProductLd(html) {
    const blocks = [...html.matchAll(/<script[^>]*type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)];
    const walk = node => {
      if (!node || typeof node !== 'object') return null;
      if (Array.isArray(node)) { for (const n of node) { const f = walk(n); if (f) return f; } return null; }
      const type = [].concat(node['@type'] || []).map(String);
      if (type.some(t => /^(Product|ProductGroup|IndividualProduct)$/i.test(t))) return node;
      return walk(node['@graph']) || null;
    };
    for (const b of blocks) { try { const f = walk(JSON.parse(b[1].trim())); if (f) return f; } catch {} }
    return null;
  }
  const meta = (html, prop) => {
    const re = new RegExp(`<meta[^>]+(?:property|name|itemprop)=["']${prop}["'][^>]*>`, 'gi');
    return [...html.matchAll(re)].map(m => (m[0].match(/content=["']([^"']*)["']/i) || [])[1]).filter(Boolean).map(decodeHtml);
  };

  async function readPage(page) {
    const r = await get(page.url, false, 8000);
    if (r.blocked) {
      out.push({ kind: 'notice', origin: page.origin, reason: `${r.blocked} while reading product pages - whitelist the n8n server IP` });
      blockedHosts.add(page.origin);
      return;
    }
    const html = r.text || '';
    const node = findProductLd(html);
    if (!node && !/product/i.test(meta(html, 'og:type')[0] || '') && !meta(html, 'product:price:amount').length) return;

    const ld = node || {};
    let offers = [].concat(ld.offers || (ld.hasVariant || []).map(v => v.offers) || []).flat().filter(Boolean);
    if (offers[0]?.offers) offers = [].concat(offers[0].offers);
    const offer = offers.find(o => o.price || o.lowPrice) || offers[0] || {};
    const price = Number(String(offer.price ?? offer.lowPrice ?? meta(html, 'product:price:amount')[0] ?? meta(html, 'og:price:amount')[0] ?? '').replace(/[^0-9.]/g, ''));
    const rating = ld.aggregateRating || {};
    const images = httpsImages([page.sitemap_images || [], ld.image || [], meta(html, 'og:image'), meta(html, 'og:image:secure_url')]).slice(0, 30);
    const title = decodeHtml(ld.name || meta(html, 'og:title')[0] || (html.match(/<title>([^<]*)<\/title>/i) || [])[1]);

    if (title && images.length && inPriceRange(price, c) && isLeatherJacket(title + ' ' + page.url.replace(/^https?:\/\/[^\/]+/, ''), c.allow_faux)) {
      out.push({
        ...siteBase(page.origin),
        kind: 'product',
        product_id: page.url_hash,
        is_bestseller: !!page.is_bestseller,
        listed_at: page.listed_at || null,
        url_hash: page.url_hash,
        product_name: title,
        product_link: page.url.split('?')[0],
        source_price: Number.isFinite(price) && price > 0 ? price : null,
        source_currency: offer.priceCurrency || meta(html, 'product:price:currency')[0] || 'USD',
        image_urls: images,
        description: stripHtml(ld.description || meta(html, 'og:description')[0] || meta(html, 'description')[0]),
        brand: decodeHtml(typeof ld.brand === 'string' ? ld.brand : ld.brand?.name || ''),
        rating: Number(rating.ratingValue || 0),
        review_count: Number(rating.reviewCount || rating.ratingCount || 0),
        raw_details: {
          platform: 'generic',
          sku: ld.sku || '',
          availability: String(offer.availability || '').replace(/^https?:\/\/schema\.org\//, ''),
          material: ld.material || '',
          color: ld.color || ''
        }
      });
    }
  }

  // Read pages in parallel: up to 4 at a time per site, every site at the same time. Stops early if a site blocks us.
  const blockedHosts = new Set();
  const pages = $input.all().map(i => i.json);
  const byHost = {};
  for (const p of pages) (byHost[p.origin] ||= []).push(p);
  const started = Date.now();
  await Promise.all(Object.values(byHost).map(async list => {
    let next = 0;
    await Promise.all(Array.from({ length: Math.min(4, list.length) }, async () => {
      while (next < list.length && Date.now() - started < 48000) {
        const page = list[next++];
        if (blockedHosts.has(page.origin)) return;
        try { await readPage(page); } catch {}
        await wait(150);
      }
    }));
  }));
  try {
    const cfg = $('Hunt Config').first().json;
    if (cfg.run_id) await this.helpers.httpRequest({ url: cfg.dashboard_url + '/api/hunt/progress', method: 'POST', headers: { 'X-Ingestion-Key': KEY() }, body: { runId: cfg.run_id, step: 'Reading product pages', status: 'running', detail: pages.length + ' pages read in the latest batch' }, json: true, timeout: 5000 });
  } catch (e) {}
  return out.map(json => ({ json }));

// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
function isLeatherJacket(text, allowFaux) {
  const t = String(text || '').toLowerCase().replace(/%20|[-_/+]+/g, ' ');
  if (!/\bleather\b|\bsuede\b|\bshearling\b|\bnappa\b|\blambskin\b|\bcowhide\b/.test(t)) return false;
  if (!/\b(jacket|jackets|bomber|biker|moto|motorcycle|racer|trucker|aviator|blouson|shacket)\b/.test(t)) return false;
  // other products that mention leather jackets (a jacket "with belt", a "shirt jacket" or "wool lining" still counts)
  if (/\b(vest|waistcoat|gilet|pants|trousers|skirt|chaps|pattern|pdf|patch|patches|sticker|keychain|keyring|key ring|wallet|bag|purse|gloves|boots|shoes|hanger|cleaner|conditioner|toy|doll|barbie|dog|helmet|lot of|bundle|phone case|case for|earring|earrings|necklace|magnet|ornament|miniature)\b/.test(t)) return false;
  if (/\b(overcoat|trench|duster|parka|peacoat|tuxedo|suit|suits|turtleneck|sweater|hoodie only)\b/.test(t)) return false;
  if (/\b(coat|coats)\b/.test(t) && !/\bjackets?\b/.test(t)) return false;
  if (!allowFaux && /\b(faux|vegan|pu leather|pleather|leatherette|imitation|synthetic leather)\b/.test(t)) return false;
  return true;
}

function inPriceRange(price, cfg) {
  const p = Number(price);
  if (!Number.isFinite(p) || p <= 0) return cfg.include_unpriced === true;
  return p >= cfg.min_price && p <= cfg.max_price;
}

function httpsImages(values) {
  return [...new Set(values.flat(Infinity).map(v => typeof v === 'string' ? v : (v && (v.imageUrl || v.url_fullxfull || v.url_570xN || v.contentUrl || v.url || v.src)) || '')
    .map(v => String(v || '').trim().replace(/&amp;/g, '&').replace(/^\/\//, 'https://').replace(/^http:\/\//i, 'https://'))
    .filter(v => /^https:\/\//i.test(v))
    .filter(v => !/\.(gif|svg)(\?|$)/i.test(v))
    .filter(v => !/(placeholder|no[-_ ]?image|logo|favicon|sprite|icon|avatar|pixel|size[-_ ]?chart|payment|badge)/i.test(v)))];
}

function sha256(input) {
  // Pure JS SHA-256 (n8n blocks require('crypto') by default)
  const bytes = unescape(encodeURIComponent(String(input)));
  const K = [0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  const H = [0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const l = bytes.length;
  const words = [];
  for (let i = 0; i < l; i++) words[i >> 2] |= bytes.charCodeAt(i) << (24 - (i % 4) * 8);
  words[l >> 2] |= 0x80 << (24 - (l % 4) * 8);
  words[(((l + 8) >> 6) + 1) * 16 - 1] = l * 8;
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let j = 0; j < words.length; j += 16) {
    const w = Array.from({ length: 16 }, (_, k) => words[j + k] | 0);
    let [a, b, c, d, e, f, g, h] = H;
    for (let i = 0; i < 64; i++) {
      if (i >= 16) {
        const s0 = r(w[i - 15], 7) ^ r(w[i - 15], 18) ^ (w[i - 15] >>> 3);
        const s1 = r(w[i - 2], 17) ^ r(w[i - 2], 19) ^ (w[i - 2] >>> 10);
        w[i] = (w[i - 16] + s0 + w[i - 7] + s1) | 0;
      }
      const t1 = (h + (r(e, 6) ^ r(e, 11) ^ r(e, 25)) + ((e & f) ^ (~e & g)) + K[i] + w[i]) | 0;
      const t2 = ((r(a, 2) ^ r(a, 13) ^ r(a, 22)) + ((a & b) ^ (a & c) ^ (b & c))) | 0;
      h = g; g = f; f = e; e = (d + t1) | 0; d = c; c = b; b = a; a = (t1 + t2) | 0;
    }
    H[0] = (H[0] + a) | 0; H[1] = (H[1] + b) | 0; H[2] = (H[2] + c) | 0; H[3] = (H[3] + d) | 0;
    H[4] = (H[4] + e) | 0; H[5] = (H[5] + f) | 0; H[6] = (H[6] + g) | 0; H[7] = (H[7] + h) | 0;
  }
  return H.map(x => (x >>> 0).toString(16).padStart(8, '0')).join('');
}

async function report(helpers, cfg, body) {
  // Tells the dashboard how the hunt is going. Never stops the hunt if the dashboard can't be reached.
  if (!cfg || !cfg.run_id || !cfg.dashboard_url) return;
  try {
    await helpers.httpRequest({ url: cfg.dashboard_url + '/api/hunt/progress', method: 'POST', headers: { 'X-Ingestion-Key': KEY() }, body: { runId: cfg.run_id, ...body }, json: true, timeout: 5000 });
  } catch (e) {}
}

  // Scores every candidate on BEST SELLER + LATEST + quality, skips jackets already on the
  // dashboard and keeps only the best N (default 10) for this run.
  const c = $('Hunt Config').first().json;
  const helpers = this.helpers;
  if (await shouldStop(helpers)) return [];
  const items = $input.all().map(i => i.json).filter(Boolean);
  const notices = items.filter(j => j.kind === 'notice').map(j => `${j.origin}: ${j.reason}${j.requests ? ' [' + j.requests.join('; ') + ']' : ''}`);

  // Jackets saved by earlier runs (dashboard keys = sha256(source:id))
  let known = new Set();
  try {
    const res = await helpers.httpRequest({ url: c.dashboard_url + '/api/known', method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 15000 });
    const data = typeof res === 'string' ? JSON.parse(res) : res;
    known = new Set([...(data.keys || []), ...(data.contentHashes || [])]);
  } catch (e) {
    // without this list every old jacket would be saved again: stop and say why
    await report(helpers, c, { step: 'Choosing the best', status: 'error', detail: 'n8n could not reach the dashboard to check which jackets you already have', failed: true, error: 'Dashboard unreachable from n8n: ' + String(e.message || '').slice(0, 120) });
    throw new Error('Dashboard unreachable - stopping so nothing is saved twice');
  }
  // prices are compared in USD (UK / Canada listings are in their own currency)
  const FX = { USD: 1, GBP: 1.27, CAD: 0.73, EUR: 1.08, AUD: 0.66 };
  const usd = p => { const v = Number(p.source_price); return Number.isFinite(v) && v > 0 ? v * (FX[String(p.source_currency || 'USD').toUpperCase()] || 1) : v; };
  // the same photo identity the dashboard uses (Google / eBay picture ids, otherwise shop + file name)
  const imageId = u => { const s = String(u || ''); const t = s.match(/tbn:([\w-]{12,})/); if (t) return 'tbn:' + t[1]; const e = s.match(/\/images\/g\/([^/]{6,})\//); if (e) return 'ebay:' + e[1]; const m = s.match(/^https?:\/\/([^\/?#]+)([^?#]*)/i); return m ? m[1].replace(/^www\./, '') + '/' + m[2].split('/').pop().replace(/_\d+x\d*|_(?:large|grande|master)/gi, '') : s.split('?')[0].split('/').pop(); };

  function gender(text) {
    const t = String(text || '').toLowerCase();
    if (/unisex|gender[- ]neutral/.test(t)) return 'Unisex';
    if (/\b(women|womens|women's|woman|ladies|lady|female)\b/.test(t)) return 'Women';
    if (/\b(men|mens|men's|man|male|gentlemen)\b/.test(t)) return 'Men';
    return 'Unisex';
  }
  const now = Date.now();
  function ageDays(v) {
    if (v === null || v === undefined || v === '') return null;
    const t = typeof v === 'number' ? (v < 1e12 ? v * 1000 : v) : Date.parse(v);
    return Number.isFinite(t) ? Math.max(0, (now - t) / 864e5) : null;
  }

  const seen = new Set();
  const scored = [];
  for (const p of items) {
    if (!p.product_name || !p.product_link || !p.product_id) continue;
    if (!isLeatherJacket(p.product_name + (p.source === 'website' ? ' ' + String(p.product_link).replace(/^https?:\/\/[^\/]+/, '') : ''), c.allow_faux)) continue;
    if (!inPriceRange(usd(p), c)) continue;
    const images = httpsImages([p.image_urls || []]);
    if (!images.length) continue;
    const idHash = sha256(p.source + ':' + p.product_id);
    const contentHash = sha256('v2|' + String(p.product_name).toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim() + '|' + imageId(images[0]));
    if (seen.has(idHash) || seen.has(contentHash) || known.has(idHash) || known.has(contentHash)) continue;
    seen.add(idHash);
    seen.add(contentHash);

    const reasons = [];
    let best = 0, latest = 0, quality = 0;
    // Popularity: REVIEWS first (more reviews = more people bought it), then sold / favourites. Best-seller tag only a small bonus.
    // Etsy only gives the SHOP's reviews (not this listing's): a small bonus, not the listing's popularity
    const reviews = p.source === 'ebay' || p.source === 'etsy' ? 0 : Number(p.review_count || 0);
    if (p.source === 'etsy' && Number(p.review_count) > 0) { best += Math.min(8, Math.round(Math.log10(Number(p.review_count) + 1) * 2.5)); reasons.push('Shop has ' + p.review_count + ' reviews'); }
    if (reviews > 0) { best += Math.min(45, Math.round(Math.log10(reviews + 1) * 18)); reasons.push(`${reviews} reviews`); }
    if (Number(p.rating) >= 4.5 && reviews >= 5) { best += 5; reasons.push(`Rated ${Number(p.rating).toFixed(1)}`); }
    const sold = Number(p.raw_details?.estimatedSoldQuantity || 0);
    if (sold > 0) { best += Math.min(35, Math.round(Math.log10(sold + 1) * 16)); reasons.push(`${sold} sold`); }
    const fav = Number(p.raw_details?.num_favorers || 0);
    if (fav > 0) { best += Math.min(25, Math.round(Math.log10(fav + 1) * 10)); reasons.push(`${fav} favourites`); }
    if (p.is_bestseller) { best += 8; reasons.push('In the store best sellers'); }
    best = Math.min(best, 60);
    // Latest
    const age = ageDays(p.listed_at ?? p.raw_details?.original_creation_timestamp ?? p.raw_details?.creation_timestamp);
    if (age !== null) {
      if (age <= 14) latest = 15; else if (age <= 45) latest = 10; else if (age <= 120) latest = 5; else if (age <= 365) latest = 2;
      if (latest) reasons.push(age < 1 ? 'Listed today' : `Listed ${Math.round(age)} days ago`);
    }
    // Quality
    if (images.length >= 6) quality += 8; else if (images.length >= 3) quality += 4;
    if (/genuine|real leather|lambskin|cowhide|sheepskin|nappa|full grain|shearling/i.test(p.product_name + ' ' + (p.description || ''))) { quality += 6; reasons.push('Genuine leather'); }
    if (p.description && p.description.length > 80) quality += 3;
    if (Number(p.search_rank) && Number(p.search_rank) <= 5) quality += 3;
    reasons.push(`${images.length} images`);

    scored.push({
      ...p,
      run_id: c.run_id,
      id_hash: idHash,
      content_hash: contentHash,
      gender: gender(p.product_name + ' ' + p.product_link + ' ' + (p.raw_details?.localizedAspects || []).map(a => a.value).join(' ')),
      primary_image_url: images[0],
      image_urls: images.slice(0, 24),
      image_count: Math.min(images.length, 24),
      bestseller_score: best,
      latest_score: latest,
      trend_score: Math.min(100, best + latest + quality + 5),
      score_reasons: reasons,
      category: 'Leather Jacket',
      material: /suede/i.test(p.product_name) ? 'Suede Leather' : /faux|vegan|pu leather/i.test(p.product_name) ? 'Faux Leather' : 'Leather',
      price_range: { min: c.min_price, max: c.max_price },
      hunted_at: new Date().toISOString()
    });
  }

  // Must be both popular and recent where possible: rank by total, ties -> newer first
  let top;
  if (c.mode === 'trend') {
    const perTopic = {};
    top = scored.sort((a, b) => (a.search_rank || 99) - (b.search_rank || 99))
      .filter(p => (perTopic[p.trend_topic] = (perTopic[p.trend_topic] || 0) + 1) <= 10);
  } else {
    // Fair share: every site / source gets jackets in proportion to how many it offered,
    // at least 1 each and never more than 35% of the hunt, so one shop can't take everything.
    const byScore = (a, b) => b.trend_score - a.trend_score || b.bestseller_score - a.bestseller_score || b.latest_score - a.latest_score;
    const siteOf = p => p.source === 'website' ? (p.source_domain || 'website') : (p.source === 'google_shopping' ? 'google:' + (p.source_domain || '') : p.source);
    const groups = {};
    for (const p of scored) (groups[siteOf(p)] ||= []).push(p);
    for (const k in groups) groups[k].sort(byScore);
    const sites = Object.keys(groups), total = scored.length || 1, cap = Math.max(1, Math.ceil(c.top_n * 0.35));
    const quota = {};
    for (const k of sites) quota[k] = Math.min(cap, Math.max(1, Math.round(c.top_n * groups[k].length / total)));
    top = [];
    for (const k of sites.sort((x, y) => byScore(groups[x][0], groups[y][0]))) top.push(...groups[k].slice(0, quota[k]));
    top.sort(byScore);
    if (top.length > c.top_n) top = top.slice(0, c.top_n);
    // still room (few sites): fill with the best of the rest, up to the cap per site
    if (top.length < c.top_n) {
      const count = {}; for (const p of top) count[siteOf(p)] = (count[siteOf(p)] || 0) + 1;
      for (const p of scored.slice().sort(byScore)) {
        if (top.length >= c.top_n) break;
        if (top.includes(p)) continue;
        const k = siteOf(p);
        if ((count[k] || 0) >= cap && sites.length > 1) continue;
        top.push(p); count[k] = (count[k] || 0) + 1;
      }
    }
  }
  console.log(`Candidates ${scored.length}, kept best ${top.length}`);
  if (!top.length && notices.length) {
    await report(helpers, c, { step: 'Choosing the best', status: 'error', detail: notices.join(' | '), failed: true, error: 'No products to save. ' + notices.join(' | ') });
    throw new Error('No products to save. ' + notices.join(' | '));
  }
  await report(helpers, c, { step: 'Choosing the best', status: 'done', count: top.length,
    detail: `Kept ${top.length} of ${scored.length} new candidates` + (notices.length ? ` · ${notices.length} source notice(s)` : ''), ...(top.length ? {} : { finished: true }) });
  if (top.length) await report(helpers, c, { step: 'Saving jackets + photos', status: 'running', detail: `Saving ${top.length} jackets` });
  return top.map(json => ({ json }));

// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
const c = $('Hunt Config').first().json;
const saved = $input.all().reduce((n, i) => n + (Number(i.json && i.json.saved) || 0), 0); // real saves, not just answers
try {
  await this.helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/progress', method: 'POST', headers: { 'X-Ingestion-Key': KEY() },
    body: { runId: c.run_id, step: 'Saving jackets + photos', status: 'done', count: saved, detail: saved + ' jackets saved with their photos', finished: true }, json: true, timeout: 5000 });
} catch (e) {}
return [{ json: { finished: true, saved } }];

// The ingestion key arrives with the hunt request (checked by "Authorized Leather Hunt?"); it is not written in the nodes.
const KEY = () => (($('Leather Hunt Webhook').first().json || {}).headers || {})['x-ingestion-key'] || '';
// Was this hunt stopped (or timed out) in the dashboard? Then every step quits straight away.
async function shouldStop(helpers) {
  try {
    const c = $('Hunt Config').first().json;
    if (!c.run_id) return false;
    const r = await helpers.httpRequest({ url: c.dashboard_url + '/api/hunt/state?runId=' + encodeURIComponent(c.run_id), method: 'GET', headers: { 'X-Ingestion-Key': KEY() }, json: true, timeout: 5000 });
    return !!(r && r.stop);
  } catch (e) { return false; }
}
  // n8n downloads each jacket's photos (10 jackets per run, all photos in parallel, well under the 60s limit)
  // and sends them with the product, so the dashboard never depends on the store's site.
  const helpers = this.helpers;
  if (await shouldStop(helpers)) return [];
  const started = Date.now();
  const items = $input.all().map(i => i.json);
  const jobs = [];
  items.forEach((p, i) => (p.image_urls || []).slice(0, 12).forEach(url => jobs.push({ i, url })));
  const files = items.map(() => []);
  let next = 0;
  await Promise.all(Array.from({ length: Math.min(12, jobs.length) }, async () => {
    while (next < jobs.length && Date.now() - started < 45000) {
      const { i, url } = jobs[next++];
      try {
        const res = await helpers.httpRequest({ url, method: 'GET', encoding: 'arraybuffer', returnFullResponse: true, timeout: 10000 });
        const type = String(res.headers['content-type'] || '').split(';')[0].toLowerCase();
        if (!type.startsWith("image/")) continue; // e.g. a bot-check page instead of the picture
        const buf = Buffer.from(res.body);
        if (buf.length < 1000 || buf.length > 4e6) continue;
        const total = files[i].reduce((s, f) => s + f.size, 0);
        if (total + buf.length > 30e6) continue;
        files[i].push({ url, content_type: type, size: buf.length, data: buf.toString('base64') });
      } catch (e) {}
    }
  }));
  // keep the photo order the store uses
  return items.map((p, i) => ({ json: { ...p, image_files: files[i].sort((x, y) => p.image_urls.indexOf(x.url) - p.image_urls.indexOf(y.url)), images_downloaded: files[i].length } }));
